    join(nodeDir, "node_modules", "opencode-ai", "node_modules", "opencode-windows-x64", "bin"),
    // npm global install: opencode 直接在 node_modules/.bin
    join(nodeDir, "node_modules", ".bin"),
    // 也加入 node.exe 所在目录本身（nvm 可能在此放 shim）
    nodeDir
